        BigDecimal amount = exchangeRates.convert(paidAmount, from, clientCurrency, date == null ? today.date() : date);
        if (amount.signum() <= 0) {
            throw new InvoiceRejectedException("The amount is worth nothing once converted into "
                    + clientCurrency.name() + ".");
        }
        return amount;
    }

